Design a circuit that processes a 4-bit input (A) based on a 2-bit control signal (B) and produces a 3-bit output (C). The module performs four distinct operations: left shift by 1 bit when B is 00, right shift by 1 bit when B is 01, add 1 to the input when B is 10, and subtract 1 from the input when B is 11. The output C captures the relevant bits from the operation specified by B, allowing for flexible manipulation of the input data.
module top_module(
    input [3:0] A,
    input [1:0] B,
    output reg [2:0] C
);

code:
module top_module(
    input [3:0] A,
    input [1:0] B,
    output reg [2:0] C
);// Shift left by 1
wire [4:0] A_shift_left = {1'b0, A};
wire [2:0] C_shift_left = A_shift_left[3:1];
// Shift right by 1
wire [4:0] A_shift_right = {A[3], A};
wire [2:0] C_shift_right = A_shift_right[3:1];
// Add 1
wire [4:0] A_add_one = {1'b0, A} + 1;
wire [2:0] C_add_one = A_add_one[3:1];
// Subtract 1
wire [4:0] A_sub_one = {1'b0, A} - 1;
wire [2:0] C_sub_one = A_sub_one[3:1];

// Assign output based on B
always @(*) begin
    case(B)
        2'b00: C = C_shift_left;
        2'b01: C = C_shift_right;
        2'b10: C = C_add_one;
        2'b11: C = C_sub_one;
    endcase
end

endmodule

