  addr_reg_b <= #1 {aw{1'b0}}; 
  else if ( ENB ) 
  addr_reg_b <= #1 ADDRB; 
 always @(posedge CLKA) 
  if (ENA && WEA) 
  mem[ADDRA] <= #1 DIA; 
 always @(posedge CLKB) 
