description:
Design a finite state machine (FSM) that transitions between eight distinct states based on a four-bit input. The FSM has two output signals determined by the current state: one output goes HIGH when in states S0 to S3, while the other goes HIGH when in states S4 to S7. The state transitions are dictated by the values of the input signals, enabling the FSM to respond to specific patterns by moving from one state to another.
module top_module(
  input [n-1:0] in,
  output [m-1:0] out
);

code:
module top_module(
  input [n-1:0] in,
  output [m-1:0] out
);parameter n = 4; // number of input signals
parameter m = 2; // number of output signals
parameter s = 8; // number of states

reg [2:0] state; // register to hold current state

// define states and their associated output signals
parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
parameter S5 = 3'b101;
parameter S6 = 3'b110;
parameter S7 = 3'b111;

// define output signals for each state
assign out[0] = (state == S0 || state == S1 || state == S2 || state == S3) ? 1'b1 : 1'b0;
assign out[1] = (state == S4 || state == S5 || state == S6 || state == S7) ? 1'b1 : 1'b0;

// define transitions between states based on input signals
always @(*) begin
  case(state)
    S0: state = (in[0] == 1'b1) ? S1 : S0;
    S1: state = (in[1] == 1'b1) ? S3 : S2;
    S2: state = (in[2] == 1'b1) ? S3 : S1;
    S3: state = (in[3] == 1'b1) ? S4 : S0;
    S4: state = (in[0] == 1'b1) ? S5 : S4;
    S5: state = (in[1] == 1'b1) ? S7 : S6;
    S6: state = (in[2] == 1'b1) ? S7 : S5;
    S7: state = (in[3] == 1'b1) ? S0 : S4;
  endcase
end

endmodule

