module top_module(aluop,a,b,out,zero,oflow,bge_flag);input		[2:0]	aluop;
		input		[31:0]	a, b;
		output reg	[31:0]	out;
		output	bge_flag;
		output zero;
    output oflow;
	wire [31:0] sub_ab;
	wire [31:0] add_ab;
	wire 		oflow_add;
	wire 		oflow_sub;
	wire 		oflow;
	wire 		slt;

	assign zero = (out == 0);

	assign sub_ab = a - b;
	assign add_ab = a + b;

	assign oflow_add = (a[31] == b[31] && add_ab[31] != a[31]) ? 1 : 0;
	assign oflow_sub = (a[31] == b[31] && sub_ab[31] != a[31]) ? 1 : 0;

	assign oflow = (aluop == 3'b000) ? oflow_add : 0;

	assign slt = oflow_sub ? ~(a[31]) : a[31];
  assign bge_flag = (a<268435456)?1:0;

	always @(*) begin
		case (aluop)
			3'd0:  out <= add_ab;				
			3'd1:  out <= a | b;				
			3'd2:  out <= {{31{1'b0}}, slt};	
			3'd3:  out <= sub_ab;				
			3'd4:  out <= {b[15:0],16'b0};
			default: out <= 0;
		endcase
	end

endmodule

