module alu_8bit (
    input [7:0] a,
    input [7:0] b,
    input [2:0] control,
    output reg [7:0] out
);

    always @(*) begin
        case (control)
            3'b000: out = a + b;
            3'b001: out = a - b;
            3'b010: out = a & b;
            3'b011: out = a | b;
            3'b100: out = a ^ b;
            default: out = 8'b00000000;
        endcase
    end

endmodule

