Give me the complete code.

module reg_file_8x8(CLK, WE, WR_ADDR, WR_DATA, RD_ADDR1, RD_ADDR2, RD_DATA1, RD_DATA2);
input CLK;
input WE;
input [2:0] WR_ADDR;
